12: export function performRedirect () {
13:   return ({ query }: Request, res: Response, next: NextFunction) => {
14:     const toUrl: string = query.to as string
15:     if (security.isRedirectAllowed(toUrl)) {
16:       challengeUtils.solveIf(challenges.redirectCryptoCurrencyChallenge, () => { return toUrl === 'https://explorer.dash.org/address/Xr556RzuwX6hg5EGpkybbv5RanJoZN17kW' || toUrl === 'https://blockchain.info/address/1AbKfgvw9psQ41NbLi8kufDQTezwG8DRZm' || toUrl === 'https://etherscan.io/address/0x0f933ab9fcaaa782d0279c300d73750e1311eae6' })
17:       challengeUtils.solveIf(challenges.redirectChallenge, () => { return isUnintendedRedirect(toUrl) })
18:       res.redirect(toUrl)
19:     } else {
20:       res.status(406)
21:       next(new Error('Unrecognized target URL for redirect: ' + toUrl))
22:     }
23:   }
24: }
