26: function isUnintendedRedirect (toUrl: string) {
27:   let unintended = true
28:   for (const allowedUrl of security.redirectAllowlist) {
29:     unintended = unintended && !toUrl.startsWith(allowedUrl)
30:   }
31:   return unintended
32: }

